                marker_counts[grid[r][c]] += 1
    marker = marker_counts.most_common(1)[0][0]
    targets = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    template_cells = [(r,c) for r in range(h) for c in range(w)
